/*
 * A226464  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 149" within range n from the origin.
 * https://oeis.org/A226464
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 9974, u16 n <= 9974, u32 n <= 9974, u64 n <= 9974,
 *            u128 n <= 9974, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: A226464 – triangle read by rows of the one‑dimensional
 * elementary cellular automaton with Wolfram rule 149.
 * Each row r contains 2 r + 1 entries; the global index n runs over
 * the flattened triangle a(0),a(1),a(2),… .
 */

#include <stdlib.h>
#include <stdbool.h>

static seq_t *triangle_data = NULL;  /* flattened rows, indexed by global index */
static size_t   data_capacity  = 0;   /* allocated size of triangle_data */
static idx_t    computed_up_to = 0;   /* maximum global index that has been computed */
static idx_t    current_row    = 0;   /* highest fully computed row number (>=0) */

/* Return the n-th term of A226464. */
seq_t a(idx_t n)
{
    /* Ensure the global data array exists. */
    if (triangle_data == NULL) {
        data_capacity = 1;
        triangle_data = (seq_t *)malloc(data_capacity * sizeof(seq_t));
        if (triangle_data == NULL)
            return (seq_t)0;          /* allocation failure – unlikely */
        triangle_data[0] = (seq_t)0;   /* row 0 consists of a single 0 */
        computed_up_to = 0;
        current_row    = 0;
    }

    /* If the requested index is already computed, return it. */
    if (n <= computed_up_to)
        return triangle_data[n];

    /* Grow the array if necessary. */
    if ((idx_t)(n + 1) > data_capacity) {
        size_t new_cap = data_capacity * 2;
        if (new_cap < (size_t)(n + 1))
            new_cap = (size_t)(n + 1);
        seq_t *tmp = (seq_t *)realloc(triangle_data, new_cap * sizeof(seq_t));
        if (tmp == NULL)
            return (seq_t)0;          /* allocation failure – unlikely */
        triangle_data = tmp;
        data_capacity = new_cap;
    }

    /* Compute new rows up to the one containing n. */
    for (idx_t r = current_row + 1; r * r <= n; ++r) {
        /* Previous row parameters */
        idx_t prev_start = (r - 1) * (r - 1);          /* global index of row r‑1 start */
        idx_t prev_len   = 2 * (r - 1) + 1;            /* length of row r‑1 (2r‑1) */

        /* New row parameters */
        idx_t new_start = r * r;                      /* global index of row r start */
        idx_t new_len   = 2 * r + 1;                   /* length of row r (2r+1) */

        /* Ensure space for the new row. */
        idx_t needed = new_start + new_len;
        if (needed > data_capacity) {
            size_t new_cap = data_capacity * 2;
            if (new_cap < (size_t)needed)
                new_cap = (size_t)needed;
            seq_t *tmp = (seq_t *)realloc(triangle_data, new_cap * sizeof(seq_t));
            if (tmp == NULL)
                return (seq_t)0;          /* allocation failure – unlikely */
            triangle_data = tmp;
            data_capacity = new_cap;
        }

        for (idx_t k = 0; k < new_len; ++k) {
            /* Neighbor values from previous row – use 1 for out‑of‑bounds. */
            seq_t left   = (k >= 2)     ? triangle_data[prev_start + k - 2] : (seq_t)1;
            seq_t center = (k >= 1 && k <= prev_len) ? triangle_data[prev_start + k - 1] : (seq_t)1;
            seq_t right  = (k <= prev_len - 1) ? triangle_data[prev_start + k] : (seq_t)1;

            /* Rule 149: 149 >> pattern & 1.  The pattern is LCR (left,center,right). */
            unsigned int pattern = ((unsigned int)left << 2) |
                                   ((unsigned int)center << 1) |
                                   (unsigned int)right;
            seq_t value = (seq_t)((149 >> pattern) & 1);
            triangle_data[new_start + k] = value;
        }

        /* Update bookkeeping. */
        computed_up_to = (r + 1) * (r + 1) - 1; /* last global index of row r */
        current_row    = r;
    }

    /* After the loop the requested index n lies within the computed range. */
    return triangle_data[n];
}
